SELECT COUNT(*) AS canceled_orders_count
FROM orders
WHERE order_status = 'canceled';

SELECT COUNT(*) AS seller_count
FROM sellers
WHERE seller_state = 'SP';

SELECT COUNT(*) AS review_count
FROM order_reviews
WHERE review_score = 5;

SELECT COUNT(*) AS missing_product_category_count
FROM products
WHERE product_category_name IS NULL;

SELECT COUNT(DISTINCT product_category_name) AS distinct_portuguese_categories
FROM products
WHERE product_category_name NOT IN (SELECT product_category_name FROM category_translation);

SELECT payment_type, AVG(payment_installments) AS average_installments
FROM order_payments
GROUP BY payment_type;

SELECT SUM(payment_value) AS total_payment_value
FROM order_payments
WHERE order_id = '0016dfedd97fc2950e388d2971d718c7';

SELECT COUNT(*) AS undelivered_orders
FROM orders
WHERE order_delivered_customer_date IS NULL;

SELECT COUNT(*) AS no_comment_reviews
FROM order_reviews
WHERE review_comment_message IS NULL OR review_comment_message = '';

SELECT AVG(product_weight_g) AS average_product_weight
FROM products
WHERE product_weight_g IS NOT NULL;

SELECT AVG(geolocation_lat) AS average_latitude
FROM geolocation
WHERE geolocation_zip_code_prefix = '24220';
